51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    /**
60	     * Remembers, per seen {@code Idempotency-Key} header, the id of the owner originally created for
61	     * that key, so a repeated create carrying the same key returns that owner instead of creating a
62	     * duplicate. Kept in memory and keyed on the opaque client-supplied value.
63	     */
64	    private static final java.util.Map<String, Integer> IDEMPOTENCY_KEYS =
65	        new java.util.concurrent.ConcurrentHashMap<>();
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper) {
79	        this.clinicService = clinicService;
80	        this.ownerMapper = ownerMapper;
81	        this.petMapper = petMapper;
82	        this.visitMapper = visitMapper;
83	    }
84	
85	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
86	    @Override
87	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
88	        Collection<Owner> owners;
89	        if (lastName != null) {
90	            owners = this.clinicService.findOwnerByLastName(lastName);
91	        } else {
92	            owners = this.clinicService.findAllOwners();
93	        }
94	        if (owners.isEmpty()) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
103	        Owner owner = this.clinicService.findOwnerById(ownerId);
104	        if (owner == null) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
113	        // Idempotent create: if this request carries an 'Idempotency-Key' we have already seen, return
114	        // the owner originally created for that key with 200 OK, rather than creating a duplicate (which
115	        // the identity/household duplicate rules would otherwise reject with 409).
116	        String idempotencyKey = currentIdempotencyKey();
117	        if (idempotencyKey != null) {
118	            Integer existingId = IDEMPOTENCY_KEYS.get(idempotencyKey);
119	            if (existingId != null) {
120	                Owner existing = this.clinicService.findOwnerById(existingId);
121	                if (existing != null) {
122	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
123	                }
124	            }
125	        }
126	        HttpHeaders headers = new HttpHeaders();
127	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
128	        applyAddress(owner);
129	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
130	        owner.setTelephone(normalizedTelephone);
131	        owner.setEmail(normalizeEmail(owner.getEmail()));
132	        validateEmailDomain(owner.getEmail());
133	        validatePostcode(owner.getPostcode(), owner.getCity());
134	        java.time.LocalDate serverDate = java.time.LocalDate.now();
135	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
136	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
137	                "Registration date must not be later than the current server date");
138	        }
139	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
140	            ? owner.getRegistrationDate() : serverDate;
141	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
142	        owner.setRegistrationDate(businessDate);
143	        long createdToday = this.clinicService.findAllOwners().stream()
144	            .map(Owner::getRegistrationDate)
145	            .filter(businessDate::equals)
146	            .count();
147	        if (createdToday >= 100) {
148	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
149	                "The maximum number of owners for today has already been reached");
150	        }
151	        owner.setBulkSignupWarning(createdToday > 80);
152	        // The household is keyed deterministically on (normalized last name, postcode): every owner
153	        // computes the same householdId from those two fields, so owners sharing a last name and
154	        // postcode belong to the same household automatically, without any explicit linking.
155	        String lastNameKey = normalizeForHousehold(owner.getLastName());
156	        String householdId = householdId(lastNameKey, owner.getPostcode());
157	        owner.setHouseholdId(householdId);
158	        // Soft-deleted owners are excluded from all duplicate/identity detection: a deleted owner
159	        // no longer blocks a new owner that would otherwise match it.
160	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
161	            .filter(existing -> !existing.isDeleted())
162	            .filter(existing -> householdId.equals(
163	                householdId(normalizeForHousehold(existing.getLastName()), existing.getPostcode())))
164	            .toList();
165	        // All duplicate detection is expressed through the single derived identityKey
166	        // (telephone|email|householdId); a new owner is rejected only when its whole key matches.
167	        String identityKey = owner.getIdentityKey();
168	        boolean identityInUse = this.clinicService.findAllOwners().stream()
169	            .filter(existing -> !existing.isDeleted())
170	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
171	        if (identityInUse) {
172	            throw new ResponseStatusException(HttpStatus.CONFLICT,
173	                "An owner with this identity already exists");
174	        }
175	        // Because the household is keyed on (last name, postcode), a second owner sharing a last name
176	        // and postcode with an existing owner is the same household and is rejected as a household
177	        // duplicate (409). Declaring 'sharesHousehold' only bypasses this block, creating the owner as
178	        // a declared household member.
179	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
180	        if (!householdMembers.isEmpty() && !declaredHouseholdMember) {
181	            throw new ResponseStatusException(HttpStatus.CONFLICT,
182	                "An owner in this household already exists");
183	        }
184	        String cityKey = normalizeForHousehold(owner.getCity());
185	        long cityCount = this.clinicService.findAllOwners().stream()
186	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
187	            .count();
188	        if (cityCount >= 50) {
189	            throw new ResponseStatusException(HttpStatus.CONFLICT,
190	                "This city already has the maximum number of owners");
191	        }
192	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
193	        owner.setHouseholdSize(householdMembers.size() + 1);
194	        // The former soft-match (same last name and postcode, different telephone) now coincides
195	        // exactly with the household key: such an owner is either rejected as a household duplicate
196	        // above, or, when it declares 'sharesHousehold', created as a declared household member. A
197	        // declared member is not a suspected duplicate, so no owner is ever flagged here.
198	        owner.setPossibleDuplicate(false);
199	        owner.setPossibleDuplicateOf(null);
200	        owner.setCustomerCode(deduplicateCustomerCode(customerCode(owner.getCity(), owner.getPostcode(),
201	            owner.getTelephone(), owner.getLastName())));
202	        this.clinicService.saveOwner(owner);
203	        if (idempotencyKey != null) {
204	            IDEMPOTENCY_KEYS.put(idempotencyKey, owner.getId());
205	        }
206	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
207	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
208	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel(),
209	            ownerDto.getMembershipNumber());
210	        headers.setLocation(UriComponentsBuilder.newInstance()
211	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
212	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
213	    }
214	
215	    /**
216	     * Reads the current request's {@code Idempotency-Key} header, if any. Returns the trimmed header
217	     * value, or {@code null} when the header is absent, blank, or there is no active request (so a
218	     * request without the header behaves exactly as before).
219	     *
220	     * @return the non-blank idempotency key for the current request, or {@code null}
221	     */
222	    private String currentIdempotencyKey() {
223	        org.springframework.web.context.request.RequestAttributes attrs =
224	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
225	        if (!(attrs instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttrs)) {
226	            return null;
227	        }
228	        String key = servletAttrs.getRequest().getHeader("Idempotency-Key");
229	        if (key == null || key.isBlank()) {
230	            return null;
231	        }
232	        return key.trim();
233	    }
234	
235	    /**
236	     * The fixed public-holiday calendar the business-day roll skips. When an adjusted registration
237	     * date lands on one of these dates it is rolled forward to the next non-holiday business day.
238	     */
239	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
240	        java.time.LocalDate.parse("2026-01-01"), java.time.LocalDate.parse("2026-01-26"),
241	        java.time.LocalDate.parse("2026-04-25"), java.time.LocalDate.parse("2026-12-25"),
242	        java.time.LocalDate.parse("2026-12-28"));
243	
244	    /**
245	     * Rolls a registration date forward to a business day. A Saturday, Sunday or listed public
246	     * holiday is advanced one day at a time until it lands on a weekday that is not a public holiday;
247	     * a plain weekday is returned unchanged. This is applied to the effective registration date
248	     * (whether supplied in the request or defaulted to the server date) so that every stored
249	     * {@code registrationDate}, and any value derived from it, lands on a business day.
250	     *
251	     * @param date the effective registration date
252	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
253	     */
254	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
255	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
256	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
257	            || PUBLIC_HOLIDAYS.contains(date)) {
258	            date = date.plusDays(1);
259	        }
260	        return date;
261	    }
262	
263	    /**
264	     * Counts the owners that already exist (before the current create) whose first and last names
265	     * both match the supplied names, compared case-insensitively. The returned value is captured on
266	     * the new owner at creation time and does not change as further owners are added later.
267	     *
268	     * @param firstName the new owner's first name
269	     * @param lastName  the new owner's last name
270	     * @return the number of pre-existing namesake owners
271	     */
272	    private int namesakeCount(String firstName, String lastName) {
273	        return (int) this.clinicService.findAllOwners().stream()
274	            .filter(existing -> existing.getFirstName() != null
275	                && existing.getFirstName().equalsIgnoreCase(firstName)
276	                && existing.getLastName() != null
277	                && existing.getLastName().equalsIgnoreCase(lastName))
278	            .count();
279	    }
280	
281	    /**
282	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where
283	     * {@code REGION} is the canonical region derived from the owner's postcode (falling back to
284	     * the city when the postcode is absent or in no known range, see
285	     * {@link org.springframework.samples.petclinic.mapper.Localities#forCityAndPostcode}), and
286	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the
287	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike
288	     * the previous city-prefixed scheme it carries no per-city sequence number, so the identity is
289	     * a pure function of the owner's region, telephone and last name.
290	     *
291	     * @param city                the owner's city
292	     * @param postcode            the owner's postcode, may be {@code null}
293	     * @param normalizedTelephone the owner's telephone, already normalized to E.164
294	     * @param lastName            the owner's last name
295	     * @return the assigned customer code
296	     */
297	    private String customerCode(String city, String postcode, String normalizedTelephone, String lastName) {
298	        String region = org.springframework.samples.petclinic.mapper.Localities
299	            .forCityAndPostcode(city, postcode);
300	        String hash8 = sha256UpperHex((normalizedTelephone == null ? "" : normalizedTelephone)
301	            + (lastName == null ? "" : lastName), 8);
302	        return region + "-" + hash8;
303	    }
304	
305	    /**
306	     * Ensures the computed {@code customerCode} is unique across existing owners. When {@code baseCode}
307	     * does not collide with any existing owner's {@code customerCode} it is returned unchanged.
308	     * Otherwise {@code '-<n>'} is appended, using the smallest {@code n} of 2 or more that yields a
309	     * value not already in use, and that de-duplicated code is returned.
310	     *
311	     * @param baseCode the freshly computed customer code
312	     * @return {@code baseCode} if unused, otherwise {@code baseCode + "-" + n} for the smallest free n
313	     */
314	    private String deduplicateCustomerCode(String baseCode) {
315	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
316	            .map(org.springframework.samples.petclinic.model.Owner::getCustomerCode)
317	            .filter(java.util.Objects::nonNull)
318	            .collect(java.util.stream.Collectors.toSet());
319	        if (!inUse.contains(baseCode)) {
320	            return baseCode;
321	        }
322	        int n = 2;
323	        while (inUse.contains(baseCode + "-" + n)) {
324	            n++;
325	        }
326	        return baseCode + "-" + n;
327	    }
328	
329	    /**
330	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
331	     * UTF-8 bytes of {@code value}.
332	     *
333	     * @param value  the source value to hash
334	     * @param length the number of leading hex characters to return
335	     * @return the leading upper-case hex characters of the digest
336	     */
337	    private String sha256UpperHex(String value, int length) {
338	        try {
339	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
340	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
341	            StringBuilder sb = new StringBuilder(digest.length * 2);
342	            for (byte b : digest) {
343	                sb.append(String.format("%02x", b));
344	            }
345	            return sb.substring(0, length).toUpperCase(java.util.Locale.ROOT);
346	        }
347	        catch (java.security.NoSuchAlgorithmException e) {
348	            throw new IllegalStateException("SHA-256 not available", e);
349	        }
350	    }
351	
352	    /**
353	     * Normalizes a street address applied whenever an owner is created: leading and trailing
354	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
355	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
356	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
357	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
358	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
359	     * {@code '12 MAIN STREET'}.
360	     *
361	     * @param address the raw address as submitted, or {@code null} when absent
362	     * @return the normalized address, or the empty string when the value is blank
363	     */
364	    /**
365	     * Resolves and normalizes an owner's postal address, accepting either the structured form
366	     * ({@code addressLine1} plus an optional {@code addressLine2}) or the flat {@code address}
367	     * input for backward compatibility. The structured form is preferred: when a non-blank
368	     * {@code addressLine1} is supplied, both structured lines are normalized (see
369	     * {@link #normalizeAddress(String)}) and the stored {@code address} is composed from them —
370	     * the normalized {@code addressLine1}, with a single space and the normalized
371	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the flat
372	     * {@code address} input is normalized and stored, and the structured lines are cleared.
373	     *
374	     * <p>An owner is valid only when it supplies an address in one of these forms; a request with
375	     * neither a non-blank {@code addressLine1} nor a non-blank flat {@code address} is rejected.
376	     *
377	     * @param owner the owner whose address fields are resolved and normalized in place
378	     * @throws ResponseStatusException with a 400 status when no address is supplied in either form
379	     */
380	    private void applyAddress(Owner owner) {
381	        String line1 = normalizeAddress(owner.getAddressLine1());
382	        String line2 = normalizeAddress(owner.getAddressLine2());
383	        String flat = normalizeAddress(owner.getAddress());
384	        String composed;
385	        if (!line1.isEmpty()) {
386	            composed = line2.isEmpty() ? line1 : line1 + " " + line2;
387	            owner.setAddressLine1(line1);
388	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
389	        } else {
390	            composed = flat;
391	            owner.setAddressLine1(null);
392	            owner.setAddressLine2(null);
393	        }
394	        if (composed.isEmpty()) {
395	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
396	                "Address must not be blank after normalization");
397	        }
398	        owner.setAddress(composed);
399	    }
400	
401	    private String normalizeAddress(String address) {
402	        String collapsed = (address == null ? "" : address)
403	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
404	        if (collapsed.isEmpty()) {
405	            return "";
406	        }
407	        String[] tokens = collapsed.split(" ");
408	        for (int i = 0; i < tokens.length; i++) {
409	            switch (tokens[i]) {
410	                case "ST" -> tokens[i] = "STREET";
411	                case "RD" -> tokens[i] = "ROAD";
412	                case "AVE" -> tokens[i] = "AVENUE";
413	                default -> { }
414	            }
415	        }
416	        return String.join(" ", tokens);
417	    }
418	
419	    /**
420	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
421	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
422	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
423	     * empty string.
424	     *
425	     * @param value the raw value (last name or address) as submitted
426	     * @return the normalized comparison key
427	     */
428	    private String normalizeForHousehold(String value) {
429	        if (value == null) {
430	            return "";
431	        }
432	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
433	    }
434	
435	    /**
436	     * Derives the stable shared household identifier for a household, keyed on the normalized last
437	     * name and address. Because it is a pure function of those normalized keys, every owner in the
438	     * same household deterministically computes the same value. The identifier is the first 12
439	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
440	     * (the separator prevents distinct name/address pairs from colliding).
441	     *
442	     * @param lastNameKey the normalized last-name comparison key
443	     * @param addressKey  the normalized address comparison key
444	     * @return the stable household identifier
445	     */
446	    private String householdId(String lastNameKey, String postcode) {
447	        String seed = lastNameKey + "|" + (postcode == null ? "" : postcode);
448	        try {
449	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
450	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
451	            StringBuilder sb = new StringBuilder(digest.length * 2);
452	            for (byte b : digest) {
453	                sb.append(String.format("%02x", b));
454	            }
455	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
456	        }
457	        catch (java.security.NoSuchAlgorithmException e) {
458	            throw new IllegalStateException("SHA-256 not available", e);
459	        }
460	    }
461	
462	    /**
463	     * The exact number of national (subscriber) digits required for a given country calling code,
464	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
465	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
466	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
467	     */
468	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
469	        java.util.Map.of("61", 9, "1", 10);
470	
471	    /**
472	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
473	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
474	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
475	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
476	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
477	     * is stored as {@code '+61412345678'}.
478	     *
479	     * <p>In addition, when the number's country code has a fixed national-number length (see
480	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
481	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
482	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
483	     *
484	     * @param telephone the raw telephone number as submitted
485	     * @return the normalized E.164 telephone number
486	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
487	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
488	     *         for its country code
489	     */
490	    private String normalizeTelephone(String telephone) {
491	        String raw = telephone == null ? "" : telephone.trim();
492	        String digits = raw.replaceAll("\\D", "");
493	        String e164;
494	        if (raw.startsWith("+")) {
495	            e164 = "+" + digits;
496	        } else {
497	            if (digits.startsWith("0")) {
498	                digits = digits.substring(1);
499	            }
500	            e164 = "+61" + digits;
501	        }
502	        int digitCount = e164.length() - 1;
503	        if (digitCount < 8 || digitCount > 15) {
504	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
505	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
506	        }
507	        validateNationalNumberLength(e164);
508	        return e164;
509	    }
510	
511	    /**
512	     * Validates that an E.164 number's national-number length is correct for its country code.
513	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
514	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
515	     * following it must match exactly. Country codes without a fixed length are left unchecked.
516	     *
517	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
518	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
519	     *         for the country code
520	     */
521	    private void validateNationalNumberLength(String e164) {
522	        String allDigits = e164.substring(1);
523	        String bestCode = null;
524	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
525	            if (allDigits.startsWith(code)
526	                    && (bestCode == null || code.length() > bestCode.length())) {
527	                bestCode = code;
528	            }
529	        }
530	        if (bestCode == null) {
531	            return;
532	        }
533	        int nationalLength = allDigits.length() - bestCode.length();
534	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
535	        if (nationalLength != required) {
536	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
537	                "Telephone for country code '+" + bestCode + "' must have " + required
538	                    + " national digits");
539	        }
540	    }
541	
542	    /**
543	     * The inclusive 4-digit postcode range permitted for each canonical region, keyed by the
544	     * region derived from the owner's city ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
545	     * {@code Brisbane -> QLD}): NSW {@code 2000-2099}, VIC {@code 3000-3099}, QLD
546	     * {@code 4000-4099}. A city whose region is not listed here accepts any 4-digit postcode.
547	     */
548	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
549	        "NSW", new int[] {2000, 2099},
550	        "VIC", new int[] {3000, 3099},
551	        "QLD", new int[] {4000, 4099});
552	
553	    /**
554	     * Validates an owner's optional postcode against their city's region. The postcode is only
555	     * checked when present (a {@code null} postcode is accepted, keeping the request contract
556	     * backward-compatible). Its four-digit shape is already enforced by Bean Validation on the
557	     * request DTO. When the city maps to a known region (see {@link #REGION_POSTCODE_RANGES}) the
558	     * postcode must fall within that region's inclusive range; a city with no known region accepts
559	     * any 4-digit postcode.
560	     *
561	     * @param postcode the owner's postcode as submitted, or {@code null} when absent
562	     * @param city     the owner's city, used to derive the region whose range applies
563	     * @throws ResponseStatusException with a 400 status when a supplied postcode is out of range
564	     *         for the city's region
565	     */
566	    private void validatePostcode(String postcode, String city) {
567	        if (postcode == null) {
568	            return;
569	        }
570	        String region = org.springframework.samples.petclinic.mapper.Localities.forCity(city);
571	        int[] range = REGION_POSTCODE_RANGES.get(region);
572	        if (range == null) {
573	            return;
574	        }
575	        int value = Integer.parseInt(postcode);
576	        if (value < range[0] || value > range[1]) {
577	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
578	                "Postcode " + postcode + " is not valid for region " + region);
579	        }
580	    }
581	
582	    /**
583	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
584	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
585	     * (absent) or already valid.
586	     *
587	     * @param email the email address as submitted, or {@code null} when absent
588	     * @return the lower-cased email, or {@code null} when absent
589	     */
590	    private String normalizeEmail(String email) {
591	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
592	    }
593	
594	    /**
595	     * The set of disposable email domains an owner's email may not use. These throwaway-mailbox
596	     * providers are rejected because they cannot be relied on for durable contact.
597	     */
598	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
599	        "mailinator.com", "tempmail.com", "guerrillamail.com");
600	
601	    /**
602	     * Rejects an owner whose email domain is on the disposable-domain blocklist. The email has
603	     * already been normalized to lower-case, so the domain (the part after the last {@code '@'}) is
604	     * compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}. A {@code null} email
605	     * (absent) is accepted, keeping the field optional.
606	     *
607	     * @param email the normalized email address, or {@code null} when absent
608	     * @throws ResponseStatusException with a 400 status when the email domain is blocklisted
609	     */
610	    private void validateEmailDomain(String email) {
611	        if (email == null) {
612	            return;
613	        }
614	        int at = email.lastIndexOf('@');
615	        if (at < 0) {
616	            return;
617	        }
618	        String domain = email.substring(at + 1);
619	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
620	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
621	                "Email domain " + domain + " is not allowed");
622	        }
623	    }
