267	     * The starting calendar year of the fiscal year that contains the given date. The fiscal year
268	     * starts on 1 July, so a date in July or later belongs to the fiscal year starting that same
269	     * calendar year, while a date from January to June belongs to the fiscal year that started in
270	     * the previous calendar year.
271	     *
272	     * @param date the date to classify
273	     * @return the calendar year in which the containing fiscal year starts
274	     */
275	    public static int fiscalYearNumber(LocalDate date) {
276	        return date.getMonthValue() >= java.time.Month.JULY.getValue()
277	            ? date.getYear() : date.getYear() - 1;
278	    }
