311	    /**
312	     * The owner's membership points, accumulated from the membership factors. Points start at 0 and
313	     * gain 2 when an email address is present, 1 when the owner has no namesakes (namesakeCount is
314	     * 0), 2 for a household of 3 or more members, and 3 when the owner's tenure exceeds one year.
315	     *
316	     * @param owner the owner to score
317	     * @return the total membership points (never negative)
318	     */
319	    public static int membershipPoints(Owner owner) {
320	        int points = 0;
321	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
322	            points += 2;
323	        }
324	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
325	            points += 1;
326	        }
327	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
328	            points += 2;
329	        }
330	        if (tenureExceedsOneYear(owner.getRegistrationDate())) {
331	            points += 3;
332	        }
333	        return points;
